"use client";
import {FormEvent,useEffect,useMemo,useState} from "react";
type Silo={id:number;name:string;product:string;capacity:number;minimumStock:number;active:boolean};
type Client={id:number;name:string;document?:string|null;logoUrl?:string|null;primaryColor:string;secondaryColor:string;accentColor:string;active:boolean};
type M={id:number;date:string;type:"Entrada"|"Saída"|"Ajuste";qty:number;doc:string;vehicle:string;owner:string;reason?:string;adjustmentDelta?:number|null;scheduledLoadId?:number|null;siloId:number};
type ScheduledLoad={id:number;date:string;qty:number;doc:string;vehicle:string;status:string;owner:string;siloId:number};
export default function Home(){
 const [session,setSession]=useState<any>(null),[clients,setClients]=useState<Client[]>([]),[selectedClientId,setSelectedClientId]=useState<number|null>(null),[items,setItems]=useState<M[]>([]),[users,setUsers]=useState<any[]>([]),[loads,setLoads]=useState<ScheduledLoad[]>([]),[silos,setSilos]=useState<Silo[]>([]),[selectedSiloId,setSelectedSiloId]=useState(1),[logs,setLogs]=useState<any[]>([]),[tab,setTab]=useState("dashboard"),[notice,setNotice]=useState(""),[pendingEntry,setPendingEntry]=useState<ScheduledLoad|null>(null),[movementType,setMovementType]=useState<M["type"]>("Entrada");
 const [editingUser,setEditingUser]=useState<any|null>(null),[analyticsMonth,setAnalyticsMonth]=useState(new Date().toISOString().slice(0,7)),[analyticsSiloId,setAnalyticsSiloId]=useState(0);
 const clientHeader=(id=selectedClientId)=>({"x-client-id":String(id||"")});
 const load=async(clientId:number)=>{const headers=clientHeader(clientId),[m,s,si]=await Promise.all([fetch("/api/movements",{headers}),fetch("/api/scheduled",{headers}),fetch("/api/silos",{headers})]);if(m.ok)setItems((await m.json()).map((x:any)=>({...x,qty:x.qty/1000,adjustmentDelta:x.adjustmentDelta===null?null:x.adjustmentDelta/1000})));if(s.ok)setLoads((await s.json()).map((x:any)=>({...x,qty:x.qty/1000})));if(si.ok){const rows=(await si.json()).map((x:any)=>({...x,capacity:x.capacity/1000,minimumStock:x.minimumStock/1000}));setSilos(rows);setSelectedSiloId(rows.find((x:Silo)=>x.active)?.id||1)}};
 useEffect(()=>{fetch("/api/session").then(async r=>({status:r.status,...await r.json()})).then(async x=>{setSession(x);if(x.authorized){const r=await fetch("/api/clients");if(r.ok)setClients(await r.json())}})},[]);
 const selectedSilo=silos.find(x=>x.id===selectedSiloId)||silos[0],siloItems=items.filter(x=>x.siloId===selectedSiloId),siloLoads=loads.filter(x=>x.siloId===selectedSiloId),capacity=selectedSilo?.capacity||0,minimumStock=selectedSilo?.minimumStock||0;
 const stock=useMemo(()=>siloItems.reduce((s,x)=>s+movementEffect(x),0),[siloItems]),freeSpace=Math.max(0,capacity-stock),entries=siloItems.filter(x=>x.type==="Entrada").reduce((s,x)=>s+x.qty,0),exits=siloItems.filter(x=>x.type==="Saída").reduce((s,x)=>s+x.qty,0);
 const today=new Date(),tomorrow=new Date(today),fiveDaysAgo=new Date(today);tomorrow.setDate(tomorrow.getDate()+1);fiveDaysAgo.setDate(fiveDaysAgo.getDate()-4);const todayKey=localDateKey(today),tomorrowKey=localDateKey(tomorrow),fiveDaysAgoKey=localDateKey(fiveDaysAgo),activeD1Loads=siloLoads.filter(x=>(x.status==="Programada"||x.status==="Em trânsito")&&x.date<=tomorrowKey),averageExit5=siloItems.filter(x=>x.type==="Saída"&&x.date>=fiveDaysAgoKey&&x.date<=todayKey).reduce((s,x)=>s+x.qty,0)/5,projectedD1=stock+activeD1Loads.reduce((s,x)=>s+x.qty,0)-averageExit5,projectedFreeSpace=capacity-projectedD1,occupancy=capacity?Math.min(100,Math.max(0,stock/capacity*100)):0;
 const recentExits=siloItems.filter(x=>x.type==="Saída"&&new Date(x.date)>=new Date(Date.now()-30*86400000));const daily=recentExits.reduce((s,x)=>s+x.qty,0)/30;const autonomy=daily>0?stock/daily:null;
 if(!session)return <Access title="Validando acesso…" text="Aguarde enquanto sua sessão é confirmada."/>;if(session.status===401)return <Access title={session.setup?"Primeiro acesso":"Entre para continuar"} text={session.setup?"Crie a conta administradora inicial do ME STOCK.":"Use seu e-mail e senha para acessar o ME STOCK."} login setup={!!session.setup}/>;if(!session.authorized)return <Access title="Acesso indisponível" text="Sua sessão não está autorizada."/>;
 if(!selectedClientId)return <ClientAccess clients={clients} userName={session.user.name} onSelect={async id=>{setSelectedClientId(id);await load(id)}} onLogout={async()=>{await fetch("/api/auth/logout",{method:"POST"});location.reload()}}/>;
 const u=session.user,admin=u.role==="admin",first=u.name.split(" ")[0],initials=u.name.split(/\s+/).slice(0,2).map((n:string)=>n[0]).join("").toUpperCase(),mine=items.filter(x=>x.owner==u.name);
 const selectedClient=clients.find(x=>x.id===selectedClientId)!;
 async function movement(e:FormEvent<HTMLFormElement>){e.preventDefault();const f=new FormData(e.currentTarget),body={...Object.fromEntries(f),scheduledLoadId:pendingEntry?.id};const r=await fetch("/api/movements",{method:"POST",headers:{"content-type":"application/json",...clientHeader()},body:JSON.stringify(body)}),d=await r.json();setNotice(r.ok?"Movimentação registrada com sucesso.":d.error);if(r.ok){e.currentTarget.reset();setPendingEntry(null);setMovementType("Entrada");await load(selectedClientId)}}
 async function schedule(e:FormEvent<HTMLFormElement>){e.preventDefault();const f=new FormData(e.currentTarget),r=await fetch("/api/scheduled",{method:"POST",headers:{"content-type":"application/json",...clientHeader()},body:JSON.stringify(Object.fromEntries(f))});setNotice(r.ok?"Carga programada com sucesso.":"Não foi possível programar a carga.");if(r.ok){e.currentTarget.reset();await load(selectedClientId)}}
 async function openUsers(resetEdit=true){setTab("users");if(resetEdit)setEditingUser(null);const r=await fetch("/api/users");if(r.ok)setUsers(await r.json())}async function openAudit(){setTab("audit");const r=await fetch("/api/audits",{headers:clientHeader()});if(r.ok)setLogs(await r.json())}
 async function setUserActive(id:number,active:boolean){const r=await fetch("/api/users",{method:"PATCH",headers:{"content-type":"application/json"},body:JSON.stringify({id,active})});const d=await r.json().catch(()=>({}));setNotice(r.ok?(active?"Usuário reativado com sucesso.":"Usuário bloqueado com sucesso."):(d.error||"Não foi possível alterar o usuário."));if(r.ok)openUsers()}
 async function addUser(e:FormEvent<HTMLFormElement>){e.preventDefault();const f=new FormData(e.currentTarget),r=await fetch("/api/users",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({...Object.fromEntries(f),clientId:selectedClientId})}),d=await r.json();setNotice(r.ok?"Usuário criado com sucesso.":d.error);if(r.ok){e.currentTarget.reset();openUsers()}}
 async function updateUser(e:FormEvent<HTMLFormElement>){e.preventDefault();const f=new FormData(e.currentTarget),body={...Object.fromEntries(f),id:editingUser.id},r=await fetch("/api/users",{method:"PATCH",headers:{"content-type":"application/json"},body:JSON.stringify(body)}),d=await r.json().catch(()=>({}));setNotice(r.ok?"Usuário atualizado com sucesso.":d.error||"Não foi possível atualizar o usuário.");if(r.ok){if(d.sessionRevoked&&editingUser.id===u.id){location.reload();return}setEditingUser(null);await openUsers(false)}}
 async function setLoad(loadItem:ScheduledLoad,status:string){const r=await fetch("/api/scheduled",{method:"PATCH",headers:{"content-type":"application/json",...clientHeader()},body:JSON.stringify({id:loadItem.id,status})});const d=await r.json().catch(()=>({}));if(!r.ok){setNotice(d.error||"Não foi possível alterar a programação.");return}await load(selectedClientId);if(status==="Recebida"){setSelectedSiloId(loadItem.siloId);setPendingEntry({...loadItem,status});setNotice("Programação recebida. Informe o volume e o veículo efetivamente recebidos.");setTab("new")}}
 async function deleteMovement(item:M){if(!confirm(`Excluir o lançamento ${item.type} de ${item.qty.toFixed(2)} t, documento ${item.doc}?\n\nEsta ação ficará registrada na auditoria.`))return;const r=await fetch("/api/movements",{method:"DELETE",headers:{"content-type":"application/json",...clientHeader()},body:JSON.stringify({id:item.id})}),d=await r.json().catch(()=>({}));setNotice(r.ok?"Lançamento excluído com sucesso.":d.error||"Não foi possível excluir o lançamento.");if(r.ok)await load(selectedClientId)}
 async function addSilo(e:FormEvent<HTMLFormElement>){e.preventDefault();const f=new FormData(e.currentTarget),r=await fetch("/api/silos",{method:"POST",headers:{"content-type":"application/json",...clientHeader()},body:JSON.stringify(Object.fromEntries(f))}),d=await r.json().catch(()=>({}));setNotice(r.ok?"Silo criado com sucesso.":d.error||"Não foi possível criar o silo.");if(r.ok){e.currentTarget.reset();await load(selectedClientId)}}
 async function editSilo(silo:Silo){const capacity=prompt(`Capacidade do ${silo.name} (t):`,String(silo.capacity));if(capacity===null)return;const minimumStock=prompt(`Estoque mínimo do ${silo.name} (t):`,String(silo.minimumStock));if(minimumStock===null)return;const r=await fetch("/api/silos",{method:"PATCH",headers:{"content-type":"application/json",...clientHeader()},body:JSON.stringify({id:silo.id,capacity,minimumStock})}),d=await r.json().catch(()=>({}));setNotice(r.ok?"Silo atualizado com sucesso.":d.error||"Não foi possível atualizar o silo.");if(r.ok)await load(selectedClientId)}
 async function addClient(e:FormEvent<HTMLFormElement>){e.preventDefault();const form=e.currentTarget,f=new FormData(form),file=f.get("logo") as File,logoDataUrl=file?.size?await fileToDataUrl(file):null,body={...Object.fromEntries(f),logo:undefined,logoDataUrl};const r=await fetch("/api/clients",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify(body)}),d=await r.json().catch(()=>({}));setNotice(r.ok?"Cliente cadastrado com sucesso.":d.error||"Não foi possível cadastrar o cliente.");if(r.ok){form.reset();const list=await fetch("/api/clients");if(list.ok)setClients(await list.json())}}
 async function logout(){await fetch("/api/auth/logout",{method:"POST"});location.reload()}
 const status=stock<minimumStock?"Crítico":stock<=minimumStock*2?"Atenção":"Normal";
 return <main className="clientTheme" style={{"--client-primary":selectedClient.primaryColor,"--client-secondary":selectedClient.secondaryColor,"--client-accent":selectedClient.accentColor} as React.CSSProperties}><header className="topbar"><div className="brand clientBrand">{selectedClient.logoUrl?<img src={selectedClient.logoUrl} alt={`Logo ${selectedClient.name}`}/>:<strong>{selectedClient.name}</strong>}<span>ME STOCK · Gestão de Estoque e Registros</span></div><h1>{new Date().getHours()<12?"Bom dia":new Date().getHours()<18?"Boa tarde":"Boa noite"}, <em>{first}</em></h1><div className="account"><button type="button" className="changeClient" onClick={()=>{setSelectedClientId(null);setItems([]);setLoads([]);setSilos([]);setTab("dashboard")}}>{selectedClient.name} · trocar</button><span className="rolePill">{admin?"Administrador":"Operador"}</span><div className="accountAvatar">{initials}</div></div></header>
 <nav><N t="dashboard" tab={tab} set={setTab} i="▦" l="Dashboard"/><N t="analytics" tab={tab} set={setTab} i="▥" l="Analítica"/><N t="new" tab={tab} set={setTab} i="＋" l="Lançamento"/><N t="history" tab={tab} set={setTab} i="☷" l="Histórico"/><N t="scheduled" tab={tab} set={setTab} i="▣" l="Programação"/><N t="mine" tab={tab} set={setTab} i="◎" l="Minha atividade"/>{admin&&<><N t="silos" tab={tab} set={setTab} i="◫" l="Silos"/><N t="clients" tab={tab} set={setTab} i="▤" l="Clientes"/><button className={tab==="audit"?"active":""} onClick={openAudit}>⌁ <span>Auditoria</span></button><button className={tab==="users"?"active":""} onClick={openUsers}>♙ <span>Usuários</span></button></>}</nav>
 {tab==="analytics"&&<div className="shell analyticsShell"><AnalyticsPage items={items} silos={silos} month={analyticsMonth} setMonth={setAnalyticsMonth} siloId={analyticsSiloId} setSiloId={setAnalyticsSiloId} clientName={selectedClient.name}/></div>}
 <div className="shell">{tab==="dashboard"&&<><section className="siloOverview">{silos.filter(x=>x.active).map(silo=>{const siloStock=items.filter(x=>x.siloId===silo.id).reduce((sum,item)=>sum+movementEffect(item),0),siloOccupancy=silo.capacity?Math.max(0,Math.min(100,siloStock/silo.capacity*100)):0;return <button key={silo.id} type="button" className={selectedSiloId===silo.id?"selected":""} onClick={()=>setSelectedSiloId(silo.id)}><span>{silo.name}</span><b>{silo.product}</b><strong>{siloStock.toFixed(2)} t</strong><small>{(silo.capacity-siloStock).toFixed(2)} t livres · {silo.capacity.toFixed(0)} t capacidade</small><i><em style={{width:`${siloOccupancy}%`}}/></i></button>})}</section><div className="siloChoice"><label>Visualizar silo<select value={selectedSiloId} onChange={e=>setSelectedSiloId(Number(e.target.value))}>{silos.filter(x=>x.active).map(x=><option key={x.id} value={x.id}>{x.name} — {x.product}</option>)}</select></label></div><section className="hero"><div className="heroMetrics"><div className="heroMetric"><p>ESTOQUE DISPONÍVEL · {selectedSilo?.product}</p><strong>{stock.toFixed(2)}<small> t</small></strong><span className={`badge ${status==="Normal"?"ok":status==="Atenção"?"warn":"danger"}`}>{status}</span></div><div className="heroMetric freeSpace"><p>ESPAÇO LIVRE · {selectedSilo?.name}</p><strong>{freeSpace.toFixed(2)}<small> t</small></strong><span className="capacityNote">de {capacity.toFixed(0)} t de capacidade</span></div></div><div className="siloVisual"><img src="/silo-production.png" alt={`${selectedSilo?.name} de ${selectedSilo?.product}`}/><b>Ocupação atual · {occupancy.toFixed(1)}%</b><div className="occupancyTrack"><span style={{width:`${occupancy}%`}}/></div><p>Mínimo: {minimumStock.toFixed(0)} t · Capacidade: {capacity.toFixed(0)} t</p></div></section>{projectedFreeSpace<0?<section className="operationalAlert danger"><b>⚠ Capacidade projetada do {selectedSilo?.name} excedida em {Math.abs(projectedFreeSpace).toFixed(2)} t até D+1</b><span>Considera apenas as cargas deste silo até amanhã e a média de saída dos últimos 5 dias.</span></section>:<section className="operationalAlert ok"><b>Espaço livre projetado D+1: {projectedFreeSpace.toFixed(2)} t</b><span>Já descontada a média de saída deste silo nos últimos 5 dias: {averageExit5.toFixed(2)} t/dia.</span></section>}<section className="scheduleSummary"><StatusSummary status="Programada" count={siloLoads.filter(x=>x.status==="Programada").length}/><StatusSummary status="Em trânsito" count={siloLoads.filter(x=>x.status==="Em trânsito").length}/><StatusSummary status="Recebida" count={siloLoads.filter(x=>x.status==="Recebida").length}/><StatusSummary status="Cancelada" count={siloLoads.filter(x=>x.status==="Cancelada").length}/></section><section className="cards four"><Card i="↘" c="green" l="Entradas" v={`${entries.toFixed(2)} t`} s={selectedSilo?.product}/><Card i="↗" c="blue" l="Saídas" v={`${exits.toFixed(2)} t`} s={selectedSilo?.product}/><Card i="◒" c="orange" l="Autonomia" v={autonomy?`${autonomy.toFixed(1)} dias`:"Sem consumo"} s="Média dos últimos 30 dias"/><Card i="▣" c={projectedFreeSpace<0?"orange":"blue"} l="Estoque projetado D+1" v={`${projectedD1.toFixed(2)} t`} s={`${activeD1Loads.length} carga${activeD1Loads.length===1?"":"s"} ativa${activeD1Loads.length===1?"":"s"} · saída média ${averageExit5.toFixed(2)} t`}/></section><Panel title={`Histórico recente · ${selectedSilo?.product||""}`}><Table items={siloItems.slice(0,5)} silos={silos}/></Panel></>}
 {tab==="new"&&<section className="formPanel"><div className="formIntro"><span>＋</span><p>NOVO LANÇAMENTO</p><h2>Registrar movimentação</h2><small>{pendingEntry?`Entrada originada da programação #${pendingEntry.id}. O silo é preservado automaticamente.`:movementType==="Ajuste"?"Informe o nível físico correto do silo escolhido.":"Escolha o silo antes de registrar a movimentação."}</small></div><form key={pendingEntry?.id||"manual"} onSubmit={movement}><label>Silo<select name="siloId" defaultValue={pendingEntry?.siloId||selectedSiloId} disabled={!!pendingEntry} required>{silos.filter(x=>x.active).map(x=><option key={x.id} value={x.id}>{x.name} — {x.product} ({x.capacity.toFixed(0)} t)</option>)}</select>{pendingEntry&&<input type="hidden" name="siloId" value={pendingEntry.siloId}/>}</label><label>Tipo{pendingEntry?<><input value="Entrada" readOnly/><input type="hidden" name="type" value="Entrada"/></>:<select name="type" value={movementType} onChange={e=>setMovementType(e.target.value as M["type"])} required><option>Entrada</option><option>Saída</option>{admin&&<option>Ajuste</option>}</select>}</label><div className="two"><label>Data<input name="date" type="date" defaultValue={new Date().toISOString().slice(0,10)} required/></label><label>{pendingEntry?"Volume recebido (t)":movementType==="Ajuste"?"Nível correto atual (t)":"Quantidade (t)"}<input name="qty" type="number" min="0.01" step="0.01" defaultValue={pendingEntry?.qty} required/>{movementType==="Ajuste"&&!pendingEntry&&<small className="fieldHint">O saldo final deste silo ficará exatamente neste nível.</small>}{pendingEntry&&<small className="fieldHint">Ajuste para o volume real recebido.</small>}</label></div><div className="two"><label>Documento<input name="doc" defaultValue={pendingEntry?.doc} readOnly={!!pendingEntry} required/></label><label>Veículo<input name="vehicle" defaultValue={pendingEntry?.vehicle} required/>{pendingEntry&&<small className="fieldHint">Ajuste para o veículo que realizou a entrega.</small>}</label></div>{admin&&!pendingEntry&&<label>Justificativa do ajuste<input name="reason" placeholder="Obrigatória somente para ajustes" required={movementType==="Ajuste"}/></label>}<label>Responsável<input value={u.name} readOnly/></label><Msg v={notice}/><button className="primary">{pendingEntry?"Registrar entrada":movementType==="Ajuste"?"Confirmar novo nível":"Registrar movimentação"}</button></form></section>}
 {tab==="history"&&<><div className="siloChoice"><label>Filtrar histórico por silo<select value={selectedSiloId} onChange={e=>setSelectedSiloId(Number(e.target.value))}>{silos.map(x=><option key={x.id} value={x.id}>{x.name} — {x.product}</option>)}</select></label></div><Msg v={notice}/><Panel title={`Histórico · ${selectedSilo?.product||""}`}><Table items={siloItems} silos={silos} onDelete={admin?deleteMovement:undefined}/></Panel></>}
 {tab==="mine"&&<><section className="profileHero"><div className="profileAvatar">{initials}</div><div><p>ÁREA PESSOAL</p><h2>{u.name}</h2><span>{admin?"Administrador":"Operador"}</span></div><div className="personalKpi"><small>Meus lançamentos</small><b>{mine.length}</b></div><div className="personalKpi"><small>Volume movimentado</small><b>{mine.reduce((s,x)=>s+x.qty,0).toFixed(2)} t</b></div></section><Panel title="Lançamentos realizados por mim"><Table items={mine} silos={silos}/></Panel></>}
 {tab==="scheduled"&&<section className="usersGrid"><section className="panel userForm"><div className="panelTitle"><div><p>RECEBIMENTOS</p><h2>Programar carga</h2></div></div><form onSubmit={schedule}><label>Silo<select name="siloId" defaultValue={selectedSiloId} onChange={e=>setSelectedSiloId(Number(e.target.value))} required>{silos.filter(x=>x.active).map(x=><option key={x.id} value={x.id}>{x.name} — {x.product}</option>)}</select></label><label>Data prevista<input name="date" type="date" required/></label><label>Quantidade (t)<input name="qty" type="number" step="0.01" required/></label><label>Documento<input name="doc" required/></label><label>Veículo<input name="vehicle" required/></label><Msg v={notice}/><button className="primary">Programar carga</button></form></section><Panel title="Cargas previstas"><div className="siloChoice inPanel"><label>Mostrar programações do silo<select value={selectedSiloId} onChange={e=>setSelectedSiloId(Number(e.target.value))}>{silos.map(x=><option key={x.id} value={x.id}>{x.name} — {x.product}</option>)}</select></label></div><div className="scheduleSummary compact" style={{gridTemplateColumns:"repeat(3, 1fr)"}}><StatusSummary status="Programada" count={siloLoads.filter(x=>x.status==="Programada").length}/><StatusSummary status="Em trânsito" count={siloLoads.filter(x=>x.status==="Em trânsito").length}/><StatusSummary status="Cancelada" count={siloLoads.filter(x=>x.status==="Cancelada").length}/></div><div className="userList">{siloLoads.map(x=>{const launched=items.some(item=>item.scheduledLoadId===x.id),displayStatus=launched?"Entrada lançada":x.status,silo=silos.find(s=>s.id===x.siloId);return <article key={x.id} className={`loadStatus ${statusClass(displayStatus)}`}><div className="avatar">▣</div><div><b>{x.qty.toFixed(2)} t · {x.vehicle}</b><small>{silo?.name} · {silo?.product} · {new Date(x.date+"T12:00").toLocaleDateString("pt-BR")} · {x.doc}</small><span className={`statusPill ${statusClass(displayStatus)}`}>{displayStatus}</span></div><select value={x.status} disabled={launched} onChange={e=>setLoad(x,e.target.value)}><option>Programada</option><option>Em trânsito</option><option>Recebida</option><option>Cancelada</option></select></article>})}</div></Panel></section>}
 {tab==="silos"&&<section className="usersGrid"><section className="panel userForm"><div className="panelTitle"><div><p>CONFIGURAÇÃO</p><h2>Adicionar silo</h2></div></div><form onSubmit={addSilo}><label>Identificação<input name="name" placeholder="Ex.: Silo 3" required/></label><label>Produto<input name="product" placeholder="Ex.: Cimento CPV" required/></label><label>Capacidade (t)<input name="capacity" type="number" min="0.01" step="0.01" required/></label><label>Estoque mínimo (t)<input name="minimumStock" type="number" min="0" step="0.01" required/></label><Msg v={notice}/><button className="primary">Cadastrar silo</button></form></section><Panel title="Silos cadastrados"><div className="siloAdminList">{silos.map(x=>{const currentStock=items.filter(i=>i.siloId===x.id).reduce((sum,item)=>sum+movementEffect(item),0);return <article key={x.id}><div><span>{x.name}</span><h3>{x.product}</h3><small>Capacidade {x.capacity.toFixed(2)} t · Mínimo {x.minimumStock.toFixed(2)} t · Estoque {currentStock.toFixed(2)} t</small></div><button type="button" onClick={()=>editSilo(x)}>Editar limites</button></article>})}</div></Panel></section>}
 {tab==="clients"&&<section className="usersGrid"><section className="panel userForm"><div className="panelTitle"><div><p>MULTIEMPRESA</p><h2>Cadastrar cliente</h2></div></div><form onSubmit={addClient}><label>Nome do cliente<input name="name" required/></label><label>CNPJ / identificação<input name="document"/></label><label>Logo<input name="logo" type="file" accept="image/png,image/jpeg,image/webp,image/svg+xml" required/><small className="fieldHint">PNG, JPG, WebP ou SVG, até 500 KB.</small></label><div className="threeColors"><label>Cor principal<input name="primaryColor" type="color" defaultValue="#302d91" required/></label><label>Cor secundária<input name="secondaryColor" type="color" defaultValue="#d63a1f" required/></label><label>Cor de apoio<input name="accentColor" type="color" defaultValue="#ffffff" required/></label></div><Msg v={notice}/><button className="primary">Cadastrar cliente</button></form></section><Panel title="Clientes cadastrados"><div className="clientAdminList">{clients.map(client=><article key={client.id}><div className="clientIdentity">{client.logoUrl?<img src={client.logoUrl} alt={client.name}/>:<b>{client.name}</b>}<div><strong>{client.name}</strong><small>{client.document||"Sem documento informado"}</small></div></div><div className="palettePreview"><i style={{background:client.primaryColor}}/><i style={{background:client.secondaryColor}}/><i style={{background:client.accentColor}}/></div></article>)}</div></Panel></section>}
 {tab==="audit"&&<Panel title="Trilha de auditoria"><div className="tableWrap"><table><thead><tr><th>Data e hora</th><th>Usuário</th><th>Ação</th><th>Registro</th></tr></thead><tbody>{logs.map(x=><tr key={x.id}><td>{new Date(x.createdAt).toLocaleString("pt-BR")}</td><td>{x.userEmail}</td><td>{x.action}</td><td>{x.entity} #{x.entityId}</td></tr>)}</tbody></table></div></Panel>}
 {tab==="users"&&<section className="usersGrid"><section className="panel userForm"><div className="panelTitle"><div><p>ADMINISTRAÇÃO</p><h2>{editingUser?"Editar usuário":"Criar acesso"}</h2></div></div>{editingUser?<form key={`edit-${editingUser.id}`} onSubmit={updateUser}><label>Nome<input name="name" defaultValue={editingUser.name} required/></label><label>E-mail<input name="email" type="email" defaultValue={editingUser.email} required/></label><label>Nova senha<input name="password" type="password" minLength={8} placeholder="Deixe vazio para manter a atual"/><small className="fieldHint">Ao trocar a senha, as sessões abertas deste usuário serão encerradas.</small></label><label>Perfil<select name="role" defaultValue={editingUser.role} disabled={editingUser.id===u.id}><option value="operator">Operador</option><option value="admin">Administrador</option></select>{editingUser.id===u.id&&<input type="hidden" name="role" value="admin"/>}</label><Msg v={notice}/><button className="primary">Salvar alterações</button><button type="button" className="secondaryAction" onClick={()=>setEditingUser(null)}>Cancelar</button></form>:<form onSubmit={addUser}><label>Nome<input name="name" required/></label><label>E-mail<input name="email" type="email" required/></label><label>Senha inicial<input name="password" type="password" minLength={8} required/></label><label>Perfil<select name="role"><option value="operator">Operador</option><option value="admin">Administrador</option></select></label><Msg v={notice}/><button className="primary">Criar usuário</button></form>}</section><Panel title="Usuários cadastrados"><div className="userList">{users.map(x=><article key={x.id}><div className="avatar">{x.name[0]}</div><div><b>{x.name}</b><small>{x.email} · {x.role} · {x.active?"Ativo":"Bloqueado"}</small></div><div className="userActions"><button type="button" className="editUser" onClick={()=>{setEditingUser(x);setNotice("")}}>Editar</button>{x.id!==u.id&&<button type="button" className={x.active?"block":"enable"} onClick={()=>setUserActive(x.id,!x.active)}>{x.active?"Bloquear":"Reativar"}</button>}</div></article>)}</div></Panel></section>}</div><footer><span>● {u.name} · {admin?"Administrador":"Operador"}</span><button type="button" className="logoutLink" onClick={logout}>Sair</button></footer></main>}
function ClientAccess({clients,userName,onSelect,onLogout}:{clients:Client[];userName:string;onSelect:(id:number)=>Promise<void>;onLogout:()=>Promise<void>}){
 const [loading,setLoading]=useState<number|null>(null);
 return <main className="clientAccess"><section><div className="clientAccessHead"><img src="data:image/png;base64," alt="ME STOCK" style={{width:67,height:52,objectFit:"contain",margin:"0 auto 16px",display:"block"}}/><b>ME STOCK · MULTIEMPRESA</b><h1>Selecione o cliente</h1><p>Olá, {userName.split(" ")[0]}. Escolha o ambiente que deseja acessar.</p></div><div className="clientGrid">{clients.filter(x=>x.active).map(client=><button key={client.id} type="button" disabled={loading!==null} style={{"--client-primary":client.primaryColor,"--client-secondary":client.secondaryColor} as React.CSSProperties} onClick={async()=>{setLoading(client.id);await onSelect(client.id)}}>{client.logoUrl?<img src={client.logoUrl} alt={client.name}/>:<strong>{client.name}</strong>}<span>{loading===client.id?"Carregando…":"Acessar cliente"}</span><i><em/><em/><em/></i></button>)}</div>{!clients.length&&<p className="emptyClients">Carregando clientes autorizados…</p>}<button type="button" className="clientLogout" onClick={onLogout}>Sair do ME STOCK</button></section></main>
}
function Access(p:{title:string;text:string;login?:boolean;setup?:boolean}){
 const [msg,setMsg]=useState("");
 async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();setMsg("");const f=new FormData(e.currentTarget);const body=Object.fromEntries(f);const endpoint=p.setup?"/api/auth/setup":"/api/auth/login";const r=await fetch(endpoint,{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify(body)});const d=await r.json().catch(()=>({}));if(!r.ok){setMsg(d.error||"Não foi possível acessar.");return}location.reload()}
 return <main className="access"><div className="loginCard"><img src="data:image/png;base64," alt="ME STOCK" style={{width:67,height:52,objectFit:"contain",margin:"0 auto 16px",display:"block"}}/><b>ME STOCK · ACESSO PROTEGIDO</b><h1>{p.title}</h1><p>{p.text}</p>{p.login&&<form onSubmit={submit}>{p.setup&&<label>Nome<input name="name" autoComplete="name" required/></label>}<label>E-mail<input name="email" type="email" autoComplete="email" required/></label><label>Senha<input name="password" type="password" minLength={8} autoComplete={p.setup?"new-password":"current-password"} required/></label>{p.setup&&<label>Confirmar senha<input name="confirmPassword" type="password" minLength={8} autoComplete="new-password" required/></label>}{msg&&<p className="loginError">{msg}</p>}<button className="primary" type="submit">{p.setup?"Criar administrador":"Entrar"}</button></form>}</div></main>}
function N(p:any){return <button className={p.tab===p.t?"active":""} onClick={()=>p.set(p.t)}>{p.i} <span>{p.l}</span></button>}function Card(p:any){return <article><span className={`icon ${p.c}`}>{p.i}</span><div><p>{p.l}</p><strong>{p.v}</strong><small>{p.s}</small></div></article>}function Panel(p:any){return <section className="panel"><div className="panelTitle"><div><p>ME STOCK</p><h2>{p.title}</h2></div></div>{p.children}</section>}function Msg({v}:{v:string}){return v?<p className={`notice ${v.includes("sucesso")?"success":"error"}`}>{v}</p>:null}function Table({items,silos,onDelete}:{items:M[];silos:Silo[];onDelete?:(item:M)=>void}){return <div className="tableWrap"><table><thead><tr><th>Data</th><th>Silo / Produto</th><th>Movimentação</th><th>Quantidade</th><th>Documento</th><th>Veículo</th><th>Responsável</th>{onDelete&&<th>Ações</th>}</tr></thead><tbody>{items.map(x=>{const silo=silos.find(s=>s.id===x.siloId);return <tr key={x.id}><td>{new Date(x.date+"T12:00").toLocaleDateString("pt-BR")}</td><td><b>{silo?.name||`Silo #${x.siloId}`}</b><small className="tableProduct">{silo?.product}</small></td><td><span className={`movement ${x.type.toLowerCase()}`}>{x.type}</span></td><td><b>{x.qty.toFixed(2)} t</b></td><td>{x.doc}</td><td>{x.vehicle}</td><td>{x.owner}</td>{onDelete&&<td><button type="button" className="deleteMovement" onClick={()=>onDelete(x)}>Excluir</button></td>}</tr>})}</tbody></table></div>}
function localDateKey(date:Date){const year=date.getFullYear(),month=String(date.getMonth()+1).padStart(2,"0"),day=String(date.getDate()).padStart(2,"0");return `${year}-${month}-${day}`}function statusClass(status:string){return status.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g,"").replace(/\s+/g,"-")}function StatusSummary({status,count,label}:{status:string;count:number;label?:string}){return <article className={`statusSummary ${statusClass(status)}`}><span>{count}</span><div><b>{label||status}</b><small>{label?status:"Programações"}</small></div></article>}
function movementEffect(item:M){return item.type==="Saída"?-item.qty:item.type==="Ajuste"&&item.adjustmentDelta!==null&&item.adjustmentDelta!==undefined?item.adjustmentDelta:item.qty}
function fileToDataUrl(file:File){return new Promise<string>((resolve,reject)=>{if(file.size>500000){reject(new Error("A logo deve ter até 500 KB."));return}const reader=new FileReader();reader.onload=()=>resolve(String(reader.result));reader.onerror=()=>reject(reader.error);reader.readAsDataURL(file)})}

function AnalyticsPage({items,silos,month,setMonth,siloId,setSiloId,clientName}:{items:M[];silos:Silo[];month:string;setMonth:(value:string)=>void;siloId:number;setSiloId:(value:number)=>void;clientName:string}){
 const [year,monthNumber]=month.split("-").map(Number),daysInMonth=new Date(year,monthNumber,0).getDate(),start=`${month}-01`,end=`${month}-${String(daysInMonth).padStart(2,"0")}`,chosenSilos=silos.filter(s=>s.active&&(siloId===0||s.id===siloId)),chosenIds=new Set(chosenSilos.map(s=>s.id)),periodItems=items.filter(x=>chosenIds.has(x.siloId)&&x.date>=start&&x.date<=end),entries=periodItems.filter(x=>x.type==="Entrada").reduce((sum,x)=>sum+x.qty,0),exits=periodItems.filter(x=>x.type==="Saída").reduce((sum,x)=>sum+x.qty,0),variation=periodItems.reduce((sum,x)=>sum+movementEffect(x),0),currentStock=items.filter(x=>chosenIds.has(x.siloId)).reduce((sum,x)=>sum+movementEffect(x),0),now=new Date(),isCurrent=now.getFullYear()===year&&now.getMonth()+1===monthNumber,elapsedDays=isCurrent?Math.max(1,now.getDate()):daysInMonth,dailyAverage=exits/elapsedDays;
 const days=Array.from({length:daysInMonth},(_,index)=>`${month}-${String(index+1).padStart(2,"0")}`),series=chosenSilos.map(silo=>({silo,values:days.map(day=>items.filter(x=>x.siloId===silo.id&&x.date<=day).reduce((sum,x)=>sum+movementEffect(x),0))})),allValues=series.flatMap(s=>s.values),maxValue=Math.max(1,...allValues,...chosenSilos.map(s=>s.capacity)),chartWidth=820,chartHeight=260,pad=34,point=(value:number,index:number)=>`${pad+index*(chartWidth-pad*2)/Math.max(1,daysInMonth-1)},${chartHeight-pad-value/maxValue*(chartHeight-pad*2)}`;
 const weeks=Array.from({length:Math.ceil(daysInMonth/7)},(_,index)=>{const from=index*7+1,to=Math.min(daysInMonth,from+6),rows=periodItems.filter(x=>{const day=Number(x.date.slice(8,10));return day>=from&&day<=to});return {label:`${String(from).padStart(2,"0")}–${String(to).padStart(2,"0")}`,entries:rows.filter(x=>x.type==="Entrada").reduce((s,x)=>s+x.qty,0),exits:rows.filter(x=>x.type==="Saída").reduce((s,x)=>s+x.qty,0)}}),weekMax=Math.max(1,...weeks.flatMap(x=>[x.entries,x.exits]));
 const siloConsumption=chosenSilos.map(silo=>({silo,value:periodItems.filter(x=>x.siloId===silo.id&&x.type==="Saída").reduce((sum,x)=>sum+x.qty,0)})),largestConsumption=[...siloConsumption].sort((a,b)=>b.value-a.value)[0],lowestLevel=[...series].map(s=>({silo:s.silo,value:Math.min(...s.values)})).sort((a,b)=>a.value-b.value)[0];
 function exportData(){const rows=[["Cliente","Período","Silo","Produto","Data","Tipo","Quantidade (t)","Documento","Veículo","Responsável"],...periodItems.map(x=>{const silo=silos.find(s=>s.id===x.siloId);return [clientName,month,silo?.name||"",silo?.product||"",x.date,x.type,x.qty.toFixed(2),x.doc,x.vehicle,x.owner]})],csv=rows.map(row=>row.map(value=>`"${String(value).replace(/"/g,'""')}"`).join(";")).join("\n"),blob=new Blob(["\ufeff"+csv],{type:"text/csv;charset=utf-8"}),url=URL.createObjectURL(blob),link=document.createElement("a");link.href=url;link.download=`analitica-${clientName.toLowerCase().replace(/\s+/g,"-")}-${month}.csv`;link.click();URL.revokeObjectURL(url)}
 return <section className="analyticsPage"><div className="analyticsHead"><div><p>ME STOCK · INTELIGÊNCIA OPERACIONAL</p><h2>Visão Analítica</h2><span>Indicadores de volume, consumo e oscilação dos níveis.</span></div><button type="button" onClick={exportData}>⇩ Exportar dados</button></div><div className="analyticsFilters"><label>Período<input type="month" value={month} onChange={e=>setMonth(e.target.value)}/></label><label>Silo<select value={siloId} onChange={e=>setSiloId(Number(e.target.value))}><option value={0}>Todos os silos</option>{silos.filter(s=>s.active).map(s=><option key={s.id} value={s.id}>{s.name} — {s.product}</option>)}</select></label><small>{new Date(start+"T12:00").toLocaleDateString("pt-BR")} a {new Date(end+"T12:00").toLocaleDateString("pt-BR")}</small></div><section className="analyticsKpis"><AnalyticKpi label="Estoque atual" value={`${currentStock.toFixed(2)} t`} detail={`${chosenSilos.length} silo${chosenSilos.length===1?"":"s"}`}/><AnalyticKpi label="Consumo no mês" value={`${exits.toFixed(2)} t`} detail={`${periodItems.filter(x=>x.type==="Saída").length} saídas`}/><AnalyticKpi label="Média diária" value={`${dailyAverage.toFixed(2)} t/dia`} detail={`${elapsedDays} dias considerados`}/><AnalyticKpi label="Entradas no mês" value={`${entries.toFixed(2)} t`} detail={`${periodItems.filter(x=>x.type==="Entrada").length} entradas`}/><AnalyticKpi label="Variação do estoque" value={`${variation>=0?"+":""}${variation.toFixed(2)} t`} detail={variation>=0?"Elevação no período":"Redução no período"} positive={variation>=0}/></section><div className="analyticsMain"><section className="analyticsCard levelChart"><h3>Oscilação dos níveis no mês</h3><div className="chartLegend">{chosenSilos.map((s,index)=><span key={s.id} className={`series${index%4}`}><i/> {s.product}</span>)}</div><svg viewBox={`0 0 ${chartWidth} ${chartHeight}`} role="img" aria-label="Gráfico de oscilação dos níveis"><line x1={pad} y1={chartHeight-pad} x2={chartWidth-pad} y2={chartHeight-pad} className="axis"/>{[0,.25,.5,.75,1].map(step=><g key={step}><line x1={pad} y1={chartHeight-pad-step*(chartHeight-pad*2)} x2={chartWidth-pad} y2={chartHeight-pad-step*(chartHeight-pad*2)} className="gridLine"/><text x={2} y={chartHeight-pad-step*(chartHeight-pad*2)+4}>{(maxValue*step).toFixed(0)} t</text></g>)}{series.map((s,index)=><polyline key={s.silo.id} points={s.values.map(point).join(" ")} className={`chartSeries series${index%4}`}/>)}</svg><div className="dateAxis"><span>01/{String(monthNumber).padStart(2,"0")}</span><span>{String(Math.ceil(daysInMonth/2)).padStart(2,"0")}/{String(monthNumber).padStart(2,"0")}</span><span>{daysInMonth}/{String(monthNumber).padStart(2,"0")}</span></div></section><section className="analyticsCard occupancyCard"><h3>Ocupação atual por silo</h3>{chosenSilos.map((silo,index)=>{const value=items.filter(x=>x.siloId===silo.id).reduce((sum,x)=>sum+movementEffect(x),0),pct=silo.capacity?Math.max(0,Math.min(100,value/silo.capacity*100)):0;return <article key={silo.id}><div><b>{silo.product}</b><span>{value.toFixed(2)} / {silo.capacity.toFixed(0)} t</span></div><i><em className={`series${index%4}`} style={{width:`${pct}%`}}/></i><small>{pct.toFixed(1)}% ocupado · {(silo.capacity-value).toFixed(2)} t livres</small></article>})}</section></div><div className="analyticsBottom"><section className="analyticsCard weeklyChart"><h3>Entradas x saídas por semana</h3><div className="weeklyBars">{weeks.map(week=><article key={week.label}><div><i className="barEntry" style={{height:`${week.entries/weekMax*120}px`}} title={`${week.entries.toFixed(2)} t de entradas`}/><i className="barExit" style={{height:`${week.exits/weekMax*120}px`}} title={`${week.exits.toFixed(2)} t de saídas`}/></div><b>{week.label}</b><small>{week.entries.toFixed(1)} / {week.exits.toFixed(1)} t</small></article>)}</div></section><section className="analyticsCard consumptionCard"><h3>Consumo por silo</h3>{siloConsumption.map((row,index)=><article key={row.silo.id}><div><b>{row.silo.product}</b><strong>{row.value.toFixed(2)} t</strong></div><i><em className={`series${index%4}`} style={{width:`${exits?row.value/exits*100:0}%`}}/></i></article>)}</section><section className="analyticsCard insightsCard"><h3>Destaques do período</h3><article><span>↗</span><div><small>Maior consumo</small><b>{largestConsumption?.silo.product||"Sem dados"}</b><strong>{largestConsumption?.value.toFixed(2)||"0,00"} t</strong></div></article><article><span>⚠</span><div><small>Menor nível</small><b>{lowestLevel?.silo.product||"Sem dados"}</b><strong>{lowestLevel?.value.toFixed(2)||"0,00"} t</strong></div></article><article><span>◎</span><div><small>Tendência mensal</small><b>{variation>0?"Elevação":variation<0?"Redução":"Estável"}</b><strong>{variation>=0?"+":""}{variation.toFixed(2)} t</strong></div></article></section></div></section>
}
function AnalyticKpi({label,value,detail,positive}:{label:string;value:string;detail:string;positive?:boolean}){return <article className={positive===undefined?"":positive?"positive":"negative"}><small>{label}</small><strong>{value}</strong><span>{detail}</span></article>}
